tool_calls.text:
{
  "kind": "optimization",
  "schema": {
    "$defs": {
      "Ball": {
        "additionalProperties": false,
        "properties": {
          "kind": {
            "const": "ball",
            "default": "ball",
            "title": "Kind",
            "type": "string"
          },
          "center_nm": {
            "default": [
              0.0,
              0.0,
              0.0
            ],
            "maxItems": 3,
            "minItems": 3,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Center Nm",
            "type": "array"
          },
          "radius_nm": {
            "exclusiveMinimum": 0,
            "title": "Radius Nm",
            "type": "number"
          }
        },
        "required": [
          "radius_nm"
        ],
        "title": "Ball",
        "type": "object"
      },
      "Box": {
        "additionalProperties": false,
        "properties": {
          "kind": {
            "const": "box",
            "default": "box",
            "title": "Kind",
            "type": "string"
          },
          "center_nm": {
            "default": [
              0.0,
              0.0,
              0.0
            ],
            "maxItems": 3,
            "minItems": 3,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Center Nm",
            "type": "array"
          },
          "size_nm": {
            "maxItems": 3,
            "minItems": 3,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Size Nm",
            "type": "array"
          }
        },
        "required": [
          "size_nm"
        ],
        "title": "Box",
        "type": "object"
      },
      "Circle": {
        "additionalProperties": false,
        "properties": {
          "kind": {
            "const": "circle",
            "default": "circle",
            "title": "Kind",
            "type": "string"
          },
          "center_nm": {
            "default": [
              0.0,
              0.0
            ],
            "maxItems": 2,
            "minItems": 2,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Center Nm",
            "type": "array"
          },
          "radius_nm": {
            "exclusiveMinimum": 0,
            "title": "Radius Nm",
            "type": "number"
          }
        },
        "required": [
          "radius_nm"
        ],
        "title": "Circle",
        "type": "object"
      },
      "ConstantIndex": {
        "additionalProperties": false,
        "description": "Wavelength-independent complex refractive index n + ik.",
        "properties": {
          "kind": {
            "const": "constant_index",
            "default": "constant_index",
            "title": "Kind",
            "type": "string"
          },
          "n_real": {
            "description": "Real part of the refractive index.",
            "title": "N Real",
            "type": "number"
          },
          "n_imag": {
            "default": 0.0,
            "description": "Extinction coefficient k (>= 0 for loss).",
            "minimum": 0,
            "title": "N Imag",
            "type": "number"
          }
        },
        "required": [
          "n_real"
        ],
        "title": "ConstantIndex",
        "type": "object"
      },
      "ConstantPermittivity": {
        "additionalProperties": false,
        "description": "Wavelength-independent complex relative permittivity.",
        "properties": {
          "kind": {
            "const": "constant_permittivity",
            "default": "constant_permittivity",
            "title": "Kind",
            "type": "string"
          },
          "eps_real": {
            "title": "Eps Real",
            "type": "number"
          },
          "eps_imag": {
            "default": 0.0,
            "minimum": 0,
            "title": "Eps Imag",
            "type": "number"
          }
        },
        "required": [
          "eps_real"
        ],
        "title": "ConstantPermittivity",
        "type": "object"
      },
      "DesignRegion": {
        "additionalProperties": false,
        "description": "A box whose permittivity is free: density 0 -> material_low, 1 -> material_high.",
        "properties": {
          "name": {
            "default": "design",
            "title": "Name",
            "type": "string"
          },
          "center_nm": {
            "default": [
              0.0,
              0.0,
              0.0
            ],
            "maxItems": 3,
            "minItems": 3,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Center Nm",
            "type": "array"
          },
          "size_nm": {
            "description": "Box size; z is ignored in 2D. In 3D, z is the thickness of an extruded region (e.g. the 220 nm device layer).",
            "maxItems": 3,
            "minItems": 3,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Size Nm",
            "type": "array"
          },
          "material_low": {
            "description": "Material at density 0 (usually the cladding).",
            "discriminator": {
              "mapping": {
                "constant_index": "#/$defs/ConstantIndex",
                "constant_permittivity": "#/$defs/ConstantPermittivity",
                "drude": "#/$defs/Drude",
                "drude_lorentz": "#/$defs/DrudeLorentz",
                "library": "#/$defs/LibraryMaterial",
                "tabulated": "#/$defs/Tabulated"
              },
              "propertyName": "kind"
            },
            "oneOf": [
              {
                "$ref": "#/$defs/ConstantIndex"
              },
              {
                "$ref": "#/$defs/ConstantPermittivity"
              },
              {
                "$ref": "#/$defs/Drude"
              },
              {
                "$ref": "#/$defs/DrudeLorentz"
              },
              {
                "$ref": "#/$defs/Tabulated"
              },
              {
                "$ref": "#/$defs/LibraryMaterial"
              }
            ],
            "title": "Material Low"
          },
          "material_high": {
            "description": "Material at density 1 (usually the core).",
            "discriminator": {
              "mapping": {
                "constant_index": "#/$defs/ConstantIndex",
                "constant_permittivity": "#/$defs/ConstantPermittivity",
                "drude": "#/$defs/Drude",
                "drude_lorentz": "#/$defs/DrudeLorentz",
                "library": "#/$defs/LibraryMaterial",
                "tabulated": "#/$defs/Tabulated"
              },
              "propertyName": "kind"
            },
            "oneOf": [
              {
                "$ref": "#/$defs/ConstantIndex"
              },
              {
                "$ref": "#/$defs/ConstantPermittivity"
              },
              {
                "$ref": "#/$defs/Drude"
              },
              {
                "$ref": "#/$defs/DrudeLorentz"
              },
              {
                "$ref": "#/$defs/Tabulated"
              },
              {
                "$ref": "#/$defs/LibraryMaterial"
              }
            ],
            "title": "Material High"
          },
          "init": {
            "anyOf": [
              {
                "type": "number"
              },
              {
                "const": "random",
                "type": "string"
              }
            ],
            "default": 0.5,
            "description": "Initial density, or 'random' (seeded).",
            "title": "Init"
          },
          "seed": {
            "default": 0,
            "title": "Seed",
            "type": "integer"
          },
          "filter_radius_nm": {
            "default": 0.0,
            "description": "Conic filter radius; 0 = no filter.",
            "minimum": 0,
            "title": "Filter Radius Nm",
            "type": "number"
          },
          "eta": {
            "default": 0.5,
            "description": "Projection threshold.",
            "exclusiveMaximum": 1,
            "exclusiveMinimum": 0,
            "title": "Eta",
            "type": "number"
          },
          "min_feature_nm": {
            "anyOf": [
              {
                "exclusiveMinimum": 0,
                "type": "number"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Minimum solid and void feature size, imposed with lengthscale penalties (needs filter_radius_nm >= min_feature_nm / 2).",
            "title": "Min Feature Nm"
          },
          "symmetry": {
            "description": "Mirror symmetry: 'x' = symmetric under x -> -x about the region centre, 'y' likewise; 'z' only for volumetric 3D regions.",
            "items": {
              "enum": [
                "x",
                "y",
                "z"
              ],
              "type": "string"
            },
            "title": "Symmetry",
            "type": "array"
          },
          "parametrization": {
            "default": "extruded",
            "description": "3D devices only (ignored in 2D). 'extruded': one 2D density in x-y, constant through the region's thickness size_nm[2], i.e. a single vertical etch (planar fabrication; exports to GDS). 'volumetric': a free 3D density on the grid nodes (filter and min-feature constraints act in 3D; exported layer by layer).",
            "enum": [
              "extruded",
              "volumetric"
            ],
            "title": "Parametrization",
            "type": "string"
          }
        },
        "required": [
          "size_nm",
          "material_low",
          "material_high"
        ],
        "title": "DesignRegion",
        "type": "object"
      },
      "DeviceProblem": {
        "additionalProperties": false,
        "description": "A photonic device (waveguides, couplers, gratings, ...) characterised by its S-matrix.",
        "properties": {
          "kind": {
            "const": "device",
            "default": "device",
            "title": "Kind",
            "type": "string"
          },
          "dimension": {
            "default": 3,
            "enum": [
              2,
              3
            ],
            "title": "Dimension",
            "type": "integer"
          },
          "structures": {
            "items": {
              "$ref": "#/$defs/Structure"
            },
            "title": "Structures",
            "type": "array"
          },
          "layout": {
            "anyOf": [
              {
                "$ref": "#/$defs/GdsLayout"
              },
              {
                "type": "null"
              }
            ],
            "default": null
          },
          "background": {
            "discriminator": {
              "mapping": {
                "constant_index": "#/$defs/ConstantIndex",
                "constant_permittivity": "#/$defs/ConstantPermittivity",
                "drude": "#/$defs/Drude",
                "drude_lorentz": "#/$defs/DrudeLorentz",
                "library": "#/$defs/LibraryMaterial",
                "tabulated": "#/$defs/Tabulated"
              },
              "propertyName": "kind"
            },
            "oneOf": [
              {
                "$ref": "#/$defs/ConstantIndex"
              },
              {
                "$ref": "#/$defs/ConstantPermittivity"
              },
              {
                "$ref": "#/$defs/Drude"
              },
              {
                "$ref": "#/$defs/DrudeLorentz"
              },
              {
                "$ref": "#/$defs/Tabulated"
              },
              {
                "$ref": "#/$defs/LibraryMaterial"
              }
            ],
            "title": "Background"
          },
          "domain_center_nm": {
            "default": [
              0.0,
              0.0,
              0.0
            ],
            "maxItems": 3,
            "minItems": 3,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Domain Center Nm",
            "type": "array"
          },
          "domain_size_nm": {
            "maxItems": 3,
            "minItems": 3,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Domain Size Nm",
            "type": "array"
          },
          "ports": {
            "items": {
              "$ref": "#/$defs/Port"
            },
            "minItems": 1,
            "title": "Ports",
            "type": "array"
          },
          "wavelengths": {
            "anyOf": [
              {
                "items": {
                  "type": "number"
                },
                "type": "array"
              },
              {
                "$ref": "#/$defs/WavelengthRange"
              }
            ],
            "title": "Wavelengths"
          },
          "options": {
            "additionalProperties": {
              "additionalProperties": true,
              "type": "object"
            },
            "title": "Options",
            "type": "object"
          }
        },
        "required": [
          "background",
          "domain_size_nm",
          "ports",
          "wavelengths"
        ],
        "title": "DeviceProblem",
        "type": "object"
      },
      "Drude": {
        "additionalProperties": false,
        "description": "eps(w) = eps_inf - wp^2 / (w^2 + i*gamma*w), energies in eV.",
        "properties": {
          "kind": {
            "const": "drude",
            "default": "drude",
            "title": "Kind",
            "type": "string"
          },
          "eps_inf": {
            "default": 1.0,
            "title": "Eps Inf",
            "type": "number"
          },
          "wp_ev": {
            "description": "Plasma frequency in eV.",
            "exclusiveMinimum": 0,
            "title": "Wp Ev",
            "type": "number"
          },
          "gamma_ev": {
            "description": "Damping rate in eV.",
            "minimum": 0,
            "title": "Gamma Ev",
            "type": "number"
          }
        },
        "required": [
          "wp_ev",
          "gamma_ev"
        ],
        "title": "Drude",
        "type": "object"
      },
      "DrudeLorentz": {
        "additionalProperties": false,
        "description": "eps(w) = eps_inf - wp^2/(w^2 + i g w) + sum_j d_j w0_j^2 / (w0_j^2 - w^2 - i G_j w).\n\nThe form FDTD needs for auxiliary-differential-equation dispersion.\nFit one to measured data with :func:`lightsmith.materials_fit.fit_drude_lorentz`.",
        "properties": {
          "kind": {
            "const": "drude_lorentz",
            "default": "drude_lorentz",
            "title": "Kind",
            "type": "string"
          },
          "eps_inf": {
            "default": 1.0,
            "title": "Eps Inf",
            "type": "number"
          },
          "wp_ev": {
            "default": 0.0,
            "minimum": 0,
            "title": "Wp Ev",
            "type": "number"
          },
          "gamma_ev": {
            "default": 0.0,
            "minimum": 0,
            "title": "Gamma Ev",
            "type": "number"
          },
          "poles": {
            "items": {
              "$ref": "#/$defs/LorentzPole"
            },
            "title": "Poles",
            "type": "array"
          }
        },
        "title": "DrudeLorentz",
        "type": "object"
      },
      "Ellipse": {
        "additionalProperties": false,
        "properties": {
          "kind": {
            "const": "ellipse",
            "default": "ellipse",
            "title": "Kind",
            "type": "string"
          },
          "center_nm": {
            "default": [
              0.0,
              0.0
            ],
            "maxItems": 2,
            "minItems": 2,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Center Nm",
            "type": "array"
          },
          "semi_axes_nm": {
            "maxItems": 2,
            "minItems": 2,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Semi Axes Nm",
            "type": "array"
          },
          "angle_deg": {
            "default": 0.0,
            "title": "Angle Deg",
            "type": "number"
          }
        },
        "required": [
          "semi_axes_nm"
        ],
        "title": "Ellipse",
        "type": "object"
      },
      "FieldIntensityTerm": {
        "additionalProperties": false,
        "description": "Mean |field|^2 (Hz for TE, Ez for TM; |E|^2 in 3D) in a box, with one port mode as the source.",
        "properties": {
          "weight": {
            "default": 1.0,
            "exclusiveMinimum": 0,
            "title": "Weight",
            "type": "number"
          },
          "goal": {
            "default": "maximize",
            "enum": [
              "maximize",
              "minimize",
              "target"
            ],
            "title": "Goal",
            "type": "string"
          },
          "target": {
            "anyOf": [
              {
                "type": "number"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "For goal='target': penalise (value - target)^2.",
            "title": "Target"
          },
          "aggregate": {
            "default": "mean",
            "description": "Over wavelengths. 'min' (worst-case for maximize) uses a smooth minimum.",
            "enum": [
              "mean",
              "min",
              "max"
            ],
            "title": "Aggregate",
            "type": "string"
          },
          "wavelength_weights": {
            "anyOf": [
              {
                "items": {
                  "type": "number"
                },
                "type": "array"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Per-wavelength weights for 'mean'.",
            "title": "Wavelength Weights"
          },
          "kind": {
            "const": "field_intensity",
            "default": "field_intensity",
            "title": "Kind",
            "type": "string"
          },
          "source_port": {
            "title": "Source Port",
            "type": "string"
          },
          "source_mode": {
            "default": 0,
            "minimum": 0,
            "title": "Source Mode",
            "type": "integer"
          },
          "center_nm": {
            "maxItems": 3,
            "minItems": 3,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Center Nm",
            "type": "array"
          },
          "size_nm": {
            "description": "Box size; zero sizes select a line or point.",
            "maxItems": 3,
            "minItems": 3,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Size Nm",
            "type": "array"
          }
        },
        "required": [
          "source_port",
          "center_nm",
          "size_nm"
        ],
        "title": "FieldIntensityTerm",
        "type": "object"
      },
      "GdsLayout": {
        "additionalProperties": false,
        "description": "Import geometry from a GDS file: each layer/datatype is extruded with a material.",
        "properties": {
          "path": {
            "title": "Path",
            "type": "string"
          },
          "cell": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "title": "Cell"
          },
          "layer_map": {
            "additionalProperties": {
              "additionalProperties": true,
              "type": "object"
            },
            "description": "'layer/datatype' -> {'material': Material JSON, 'z_min_nm': .., 'z_max_nm': ..}",
            "title": "Layer Map",
            "type": "object"
          }
        },
        "required": [
          "path",
          "layer_map"
        ],
        "title": "GdsLayout",
        "type": "object"
      },
      "LibraryMaterial": {
        "additionalProperties": false,
        "description": "Measured n, k bundled with lightsmith, e.g. ``{\"kind\": \"library\", \"name\": \"Au\",\n\"dataset\": \"Johnson-Christy\"}``. Linear interpolation in n and k, no extrapolation.\n\nNames and datasets accept aliases (\"gold\", \"JC\") and are stored in canonical form;\nan omitted dataset is filled with the material's default so the spec stays\nreproducible. See :func:`list_materials`.",
        "properties": {
          "kind": {
            "const": "library",
            "default": "library",
            "title": "Kind",
            "type": "string"
          },
          "name": {
            "description": "Material, e.g. 'Au', 'Ag', 'Al', 'Cu', 'Si', 'TiO2', 'SiO2', 'H2O'.",
            "title": "Name",
            "type": "string"
          },
          "dataset": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Dataset, e.g. 'Johnson-Christy'; omitted = material default.",
            "title": "Dataset"
          }
        },
        "required": [
          "name"
        ],
        "title": "LibraryMaterial",
        "type": "object"
      },
      "LorentzPole": {
        "additionalProperties": false,
        "properties": {
          "delta_eps": {
            "description": "Oscillator strength (permittivity step).",
            "title": "Delta Eps",
            "type": "number"
          },
          "omega0_ev": {
            "description": "Resonance energy in eV.",
            "exclusiveMinimum": 0,
            "title": "Omega0 Ev",
            "type": "number"
          },
          "gamma_ev": {
            "description": "Damping in eV.",
            "minimum": 0,
            "title": "Gamma Ev",
            "type": "number"
          }
        },
        "required": [
          "delta_eps",
          "omega0_ev",
          "gamma_ev"
        ],
        "title": "LorentzPole",
        "type": "object"
      },
      "OptimizerSettings": {
        "additionalProperties": false,
        "properties": {
          "method": {
            "default": "mma",
            "description": "mma = globally convergent MMA (monotone; Svanberg 2002); adam; lbfgsb = SciPy L-BFGS-B.",
            "enum": [
              "mma",
              "adam",
              "lbfgsb"
            ],
            "title": "Method",
            "type": "string"
          },
          "max_iter": {
            "default": 100,
            "description": "Total objective/gradient evaluations budget (outer iterations).",
            "minimum": 1,
            "title": "Max Iter",
            "type": "integer"
          },
          "learning_rate": {
            "default": 0.02,
            "description": "Adam step size (densities are in [0, 1]).",
            "exclusiveMinimum": 0,
            "title": "Learning Rate",
            "type": "number"
          },
          "move_limit": {
            "default": 0.2,
            "description": "MMA max change per iteration.",
            "exclusiveMinimum": 0,
            "maximum": 1,
            "title": "Move Limit",
            "type": "number"
          },
          "beta_start": {
            "default": 4.0,
            "description": "Initial projection sharpness.",
            "minimum": 0,
            "title": "Beta Start",
            "type": "number"
          },
          "beta_max": {
            "default": 64.0,
            "minimum": 0,
            "title": "Beta Max",
            "type": "number"
          },
          "beta_growth": {
            "default": 2.0,
            "description": "beta *= beta_growth every beta_every iterations (continuation).",
            "minimum": 1,
            "title": "Beta Growth",
            "type": "number"
          },
          "beta_every": {
            "default": 20,
            "minimum": 1,
            "title": "Beta Every",
            "type": "integer"
          },
          "lengthscale_weight": {
            "default": 100.0,
            "description": "Penalty weight of the min-feature constraints.",
            "minimum": 0,
            "title": "Lengthscale Weight",
            "type": "number"
          },
          "lengthscale_from_beta": {
            "default": 16.0,
            "description": "Apply min-feature penalties once beta >= this.",
            "minimum": 0,
            "title": "Lengthscale From Beta",
            "type": "number"
          },
          "ftol": {
